import sys
from bisect import bisect_right

def tm(x):
    return int(x[:2]) * 60 + int(x[3:])

def main():
    data = sys.stdin.read().split()
    p = 0
    B = int(data[p]); p += 1
    banks = {}
    for _ in range(B):
        name = data[p]; k = int(data[p + 1]); p += 2
        ivs = []
        for _ in range(k):
            ivs.append((tm(data[p]), tm(data[p + 1])))
            p += 2
        ivs.sort()
        merged = []
        for a, b in ivs:
            if merged and a <= merged[-1][1]:
                if b > merged[-1][1]:
                    merged[-1][1] = b
            else:
                merged.append([a, b])
        banks[name] = ([m[0] for m in merged], [m[1] for m in merged])
    q = int(data[p]); p += 1
    out = []
    for _ in range(q):
        name = data[p]; t = tm(data[p + 1]); p += 2
        ok = False
        if name in banks:
            starts, ends = banks[name]
            i = bisect_right(starts, t) - 1
            ok = i >= 0 and t < ends[i]
        out.append('VALID' if ok else 'INVALID')
    print('\n'.join(out))

main()

