    static int tm(String x) {
        return Integer.parseInt(x.substring(0, 2)) * 60 + Integer.parseInt(x.substring(3));
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int B = Integer.parseInt(st.nextToken());
        Map<String, List<int[]>> banks = new HashMap<>();
        for (int i = 0; i < B; i++) {
            String name = st.nextToken();
            int k = Integer.parseInt(st.nextToken());
            List<int[]> wins = new ArrayList<>();
            for (int j = 0; j < k; j++) {
                int a = tm(st.nextToken());
                int b = tm(st.nextToken());
                wins.add(new int[]{a, b});
            }
            banks.put(name, wins);
        }
        int q = Integer.parseInt(st.nextToken());
        List<Object[]> queries = new ArrayList<>();
        for (int i = 0; i < q; i++) {
            String name = st.nextToken();
            int t = tm(st.nextToken());
            queries.add(new Object[]{name, t});
        }
        boolean[] res = check(banks, queries);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) sb.append(res[i] ? "VALID" : "INVALID").append('\n');
        System.out.print(sb);
    }
}
